export const GIVING_FEEDBACK_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu umpan balik",q:"'Umpan balik' (feedback) adalah...",options:["Informasi tentang bagaimana suatu hasil kerja atau perilaku, diberikan agar bisa dipertahankan atau diperbaiki","Kritik dan celaan keras atas hasil kerja seseorang, diberikan agar ia merasa malu dan jera di depan teman","Nilai angka saja tanpa penjelasan, diberikan agar orang tahu hasil akhirnya tanpa tahu alasannya, sehingga lebih cepat"],answer:0,explain:"Umpan balik bisa positif (apa yang berjalan baik) atau perbaikan (apa yang bisa lebih baik). Keduanya berguna.",hint:"Informasi untuk memperbaiki/mempertahankan, atau sekadar celaan?"},
{n:2,type:"mcq",micro:"Tujuan umpan balik",q:"Tujuan memberi umpan balik yang baik adalah...",options:["Melampiaskan kekesalanmu supaya perasaanmu lega","Membantu orang atau hasil kerjanya menjadi lebih baik","Membuktikan kamu lebih pintar daripada orang itu"],answer:1,explain:"Kalau tujuanmu bukan membantu, itu bukan umpan balik — itu keluhan atau serangan.",hint:"Membantu jadi lebih baik, atau melampiaskan?"},
{n:3,type:"mcq",micro:"Umpan balik spesifik",q:"Mana umpan balik yang lebih berguna?",options:["'Biasa aja sih, nggak ada yang istimewa dari bagian itu.'","'Bagus kok, lanjutkan saja seperti ini ya, tidak perlu diubah.'","'Bagian pembukaanmu menarik karena langsung memberi contoh nyata.'"],answer:2,explain:"Umpan balik spesifik menyebut BAGIAN apa & MENGAPA. Yang umum ('bagus'/'biasa') tidak bisa ditindaklanjuti.",hint:"Menyebut bagian & alasan, atau umum?"},
{n:4,type:"mcq",micro:"Fokus pada perilaku/hasil",q:"Umpan balik yang baik fokus pada...",options:["Apa yang dilakukan atau dihasilkan ('presentasimu terlalu cepat')","Sifat pribadi orangnya ('kamu memang ceroboh dari dulu')","Hal yang tak bisa diubah, seperti bentuk tubuh dan suaranya"],answer:0,explain:"'Presentasimu terlalu cepat' bisa diperbaiki. 'Kamu memang ceroboh' hanya menyakiti & tidak memberi arah.",hint:"Perilaku yang bisa diubah, atau label pribadi?"},
{n:5,type:"mcq",micro:"Waktu memberi umpan balik",q:"Kapan umpan balik biasanya paling berguna?",options:["Tak ada waktu tepat, jadi biarkan sampai orang itu sadar sendiri","Cukup dekat dengan kejadiannya, saat masih segar & bisa diperbaiki","Berbulan-bulan kemudian saat kejadiannya sudah terlupakan"],answer:1,explain:"Umpan balik yang datang cepat (tapi bukan di saat orang sedang malu di depan umum) paling mudah dipakai.",hint:"Segera & relevan, atau terlambat lama?"},
{n:6,type:"mcq",micro:"Tempat memberi umpan balik perbaikan",q:"Umpan balik yang berisi kritik sebaiknya disampaikan...",options:["Di depan umum atau banyak orang supaya mereka ikut belajar","Lewat gosip ke orang lain supaya kritiknya sampai kepadanya","Empat mata / pribadi, bukan di depan banyak orang"],answer:2,explain:"'Puji di depan umum, koreksi secara pribadi' — koreksi di depan umum mempermalukan & membuat orang defensif.",hint:"Empat mata, atau di depan umum / gosip?"},
{n:7,type:"mcq",micro:"Menerima umpan balik: sikap awal",q:"Saat menerima umpan balik, sikap pertama yang membantu:",options:["Dengarkan sampai selesai sebelum membela diri; anggap ini kesempatan belajar","Langsung membantah tiap poin saat itu juga supaya pemberi masukan tahu kamu tidak salah","Menganggap pemberi masukan membencimu dan ingin menjatuhkanmu, jadi tak perlu didengar"],answer:0,explain:"Menahan dorongan defensif memberi kamu kesempatan menangkap yang berguna. Kamu bisa memilah setelahnya.",hint:"Dengar dulu, atau langsung membela diri?"},
{n:8,type:"mcq",micro:"Umpan balik positif itu penting",q:"Menyebut apa yang sudah berjalan baik ('bagian datamu akurat & rapi') berguna karena...",options:["Membuat orang jadi sombong karena merasa tak ada lagi yang perlu diperbaiki","Orang jadi tahu apa yang harus dipertahankan, & lebih terbuka menerima saran perbaikan","Membuang waktu karena orang sudah tahu sendiri apa yang harus dipertahankan"],answer:1,explain:"Umpan balik yang hanya berisi kritik terasa seperti serangan. Menyebut kekuatan juga membuat gambaran lengkap.",hint:"Menunjukkan yang perlu dipertahankan, atau buang waktu?"},
{n:9,type:"order",micro:"Memberi umpan balik sederhana",q:"Urutkan cara memberi umpan balik atas tugas teman.",items:["Tanya izin/kesiapan: 'Boleh aku kasih masukan soal esaimu?'","Sebut yang sudah bagus & spesifik: 'Argumenmu di paragraf 2 kuat.'","Sebut satu-dua hal yang bisa diperbaiki, dengan alasan & saran","Akhiri dengan dorongan & tawaran diskusi"],answer:[0,1,2,3],explain:"Izin → kekuatan spesifik → saran perbaikan + alasan → dorongan. Bukan langsung menembak kekurangan.",hint:"Apa yang dilakukan sebelum menyampaikan kekurangan?"},
{n:10,type:"mcq",micro:"Nada umpan balik",q:"Nada memberi umpan balik yang membantu:",options:["Mengejek & merendahkan","Dingin & menghakimi","Tenang, ramah, & niat membantu terasa"],answer:2,explain:"Isi yang sama bisa diterima atau ditolak tergantung nada. Nada 'aku di pihakmu' membuka telinga.",hint:"Ramah & membantu, atau mengejek?"},
{n:11,type:"tf",micro:"Umpan balik bukan hanya kritik",q:"Benar atau Salah: Umpan balik yang baik mencakup menyebut apa yang berjalan baik, bukan hanya apa yang perlu diperbaiki.",answer:true,explain:"Orang perlu tahu kekuatannya untuk mempertahankannya. Umpan balik lengkap = kekuatan + area perbaikan.",hint:"Hanya kritik, atau kekuatan + perbaikan?"},
{n:12,type:"tf",micro:"Menerima umpan balik = harus setuju?",q:"Benar atau Salah: Menerima umpan balik dengan baik berarti kamu wajib langsung setuju & menuruti semua yang dikatakan.",answer:false,explain:"Sebaliknya, kamu bisa mendengarkan dengan terbuka, berterima kasih, lalu memilah mana yang akan kamu terapkan setelah memikirkannya dengan tenang.",hint:"Wajib menuruti semua, atau dengar lalu pilah?"},
{n:13,type:"mcq",micro:"Umpan balik yang bisa ditindaklanjuti",q:"Umpan balik 'tulisanmu kurang jelas' menjadi lebih berguna kalau ditambah...",options:["'...terutama paragraf 3 — kalimatnya terlalu panjang. Coba pecah jadi dua.'","'...pokoknya kurang jelas aja, perbaiki sendiri ya, kamu tahu lah.'","'...seperti biasa, nggak ada yang baru dan menarik dari tulisanmu.'"],answer:0,explain:"Tambahkan: bagian mana, kenapa, & saran konkret. Itu mengubah keluhan jadi arahan.",hint:"Bagian + alasan + saran, atau pengulangan samar?"},
{n:14,type:"mcq",micro:"Umpan balik vs perintah",q:"'Menurutku akan lebih kuat kalau kesimpulanmu menyebut solusi. Bagaimana menurutmu?' berbeda dari 'Ganti kesimpulanmu' karena...",options:["Menyembunyikan maksudmu mengkritik dari lawan bicara","Menawarkan sudut pandang & mengundang diskusi, bukan memerintah","Lebih lemah karena kritik yang baik harus berupa perintah"],answer:1,explain:"Umpan balik terbaik terasa seperti tawaran ('pertimbangkan ini'), bukan titah, sehingga orang tetap merasa memiliki karyanya.",hint:"Tawaran + diskusi, atau perintah?"},
{n:15,type:"mcq",micro:"Bertanya sebelum memberi",q:"Sebelum memberi umpan balik yang belum diminta, bertanya 'Kamu lagi cari masukan, atau mau aku dengar aja?' berguna karena...",options:["Membuang waktu saja, karena lebih baik langsung mengkritik apa adanya tanpa bertanya ia siap mendengar","Tidak sopan bertanya begitu, karena orang seharusnya terbuka terhadap masukan dari siapa saja yang peduli","Orang mungkin belum siap atau hanya ingin berbagi; memberi saran yang tidak diminta bisa terasa menghakimi"],answer:2,explain:"Umpan balik yang tidak diminta paling baik ditawarkan, bukan dipaksakan.",hint:"Cek kesiapan dulu, atau langsung kritik?"},
{n:16,type:"mcq",micro:"Menerima pujian",q:"Cara menerima umpan balik positif dengan baik:",options:["'Terima kasih, senang mendengarnya.' — menerima dengan tulus","Menyangkal pujian: 'Ah, nggak kok, jelek banget, aku cuma beruntung.'","Menyombongkan diri: 'Ya iyalah, aku kan memang hebat dari dulu.'"],answer:0,explain:"Menerima pujian dengan sederhana & tulus lebih baik daripada menyangkal (menolak niat baik) atau sombong.",hint:"Terima tulus, atau menyangkal / sombong?"},
{n:17,type:"mcq",micro:"Umpan balik untuk diri sendiri",q:"Setelah mengerjakan sesuatu, bertanya pada diri 'Apa yang berjalan baik? Apa yang akan kuubah lain kali?' adalah...",options:["Tanda kamu tidak percaya diri dan butuh pengakuan orang lain","Umpan balik diri (refleksi) yang mempercepat belajar","Membuang waktu karena orang lain lebih tahu tentang kamu"],answer:1,explain:"Kamu bisa jadi pemberi umpan balik pertama untuk dirimu sendiri — jujur & spesifik.",hint:"Refleksi yang mempercepat belajar, atau buang waktu?"},
{n:18,type:"mcq",micro:"Umpan balik jujur tapi baik",q:"Temanmu bertanya pendapatmu tentang gambarnya yang menurutmu masih perlu banyak perbaikan. Respons yang jujur & baik:",options:["'Bagus banget! Sempurna, tak ada yang perlu diperbaiki!' (padahal itu bohong supaya ia senang), dan ia tak perlu berlatih","'Jelek, gambarmu berantakan semua. Latihan lagi sana, jangan dipamerkan kalau hasilnya masih seperti itu.'","'Warnanya berani & aku suka idenya. Menurutku proporsi tangannya bisa dilatih lagi — mau aku tunjukkan referensinya?'"],answer:2,explain:"Jujur tidak berarti kasar. Sebut yang baik + satu area + tawarkan bantuan.",hint:"Jujur + membangun, atau bohong / kasar?"},
{n:19,type:"mcq",micro:"Umpan balik & rasa aman",q:"Kelompok di mana anggota nyaman memberi & menerima umpan balik cenderung...",options:["Berkembang lebih cepat karena masalah kecil diperbaiki sebelum jadi besar","Sering bertengkar karena kritik membuat anggota saling tersinggung","Sulit maju karena tim sibuk menjaga perasaan dan menunda kritik"],answer:0,explain:"Budaya umpan balik yang aman = perbaikan terus-menerus, bukan kejutan buruk di akhir.",hint:"Berkembang cepat, atau bertengkar terus?"},
{n:20,type:"open",micro:"Menyusun umpan balik",q:"Teman sekelasmu berlatih presentasi di depanmu. Kelebihan: materinya lengkap & suaranya jelas. Kekurangan: ia membaca terus dari kertas & tidak menatap 'penonton', serta melebihi waktu. Tulis umpan balik yang akan kamu berikan (lisan), lalu jelaskan mengapa kamu menyusunnya seperti itu.",explain:"Jawaban baik: membuka dengan kekuatan spesifik, menyampaikan hanya 1-2 area perbaikan (bukan menumpuk), tiap saran disertai alasan + langkah konkret, fokus pada perilaku/hasil (bukan pribadi), nada membantu, dan menutup dengan dorongan/tawaran bantuan — lalu menjelaskan alasan struktur itu.",hint:"Kekuatan spesifik dulu, 1-2 perbaikan dengan alasan + saran konkret, tutup dengan dorongan.",sample:"Umpan balik: 'Presentasimu materinya lengkap banget dan suaramu jelas, jadi enak diikuti. Dua hal yang menurutku bisa bikin lebih kuat: pertama, coba lebih sering lihat ke penonton dan pakai kertas cuma sebagai pengingat poin, bukan dibaca semua — jadi kamu kelihatan lebih yakin dan penonton merasa diajak bicara. Kedua, tadi agak lewat waktu; mungkin bagian contoh yang ketiga bisa dipangkas supaya pas. Kamu mau latihan sekali lagi bareng aku sambil aku pegang timer?' Kenapa kusun begini: aku mulai dari kekuatan spesifik supaya ia tahu apa yang harus dipertahankan dan lebih terbuka; aku sebut hanya dua hal perbaikan (bukan sepuluh) supaya fokus dan tidak kewalahan; tiap saran kukasih alasan ('kelihatan lebih yakin') dan cara konkret ('kertas sebagai pengingat', 'pangkas contoh ketiga'); dan aku tutup dengan tawaran bantuan supaya terasa aku di pihaknya."},
{n:21,type:"classify",micro:"Umpan balik berguna vs tidak",q:"Kelompokkan tiap komentar ke 'Umpan balik berguna' atau 'Tidak berguna/menyakiti'.",items:["'Grafik di slide 3 sulit dibaca karena tulisannya kecil.'","'Kerjaanmu selalu berantakan, dasar pemalas.'","'Bagian analisismu bagus, tapi kesimpulannya belum menjawab pertanyaan awal.'","'Ya gitu deh, terserah kamu.'"],groups:["Umpan balik berguna","Tidak berguna/menyakiti"],answer:{"Umpan balik berguna":["'Grafik di slide 3 sulit dibaca karena tulisannya kecil.'","'Bagian analisismu bagus, tapi kesimpulannya belum menjawab pertanyaan awal.'"],"Tidak berguna/menyakiti":["'Kerjaanmu selalu berantakan, dasar pemalas.'","'Ya gitu deh, terserah kamu.'"]},explain:"Berguna: spesifik, fokus pada hasil, bisa ditindaklanjuti. Tidak berguna: label pribadi, terlalu umum, atau melempem tanpa isi.",hint:"Spesifik & bisa dikerjakan, atau label / kabur?"},
{n:22,type:"mcq",micro:"Model SBI (Situasi-Perilaku-Dampak)",q:"Cara menyampaikan umpan balik dengan jelas: sebut Situasi, Perilaku, lalu Dampak. Contoh yang benar:",options:["'Presentasimu jelek banget tadi, aku kurang suka, lain kali dibuat lebih bagus ya supaya tidak memalukan di depan kelas lagi.'","'Waktu presentasi tadi (situasi), kamu membaca terus dari kertas (perilaku), jadi terasa kurang terhubung dengan penonton (dampak).'","'Kamu emang nggak percaya diri ya, makanya presentasi kelihatan gugup, berantakan, dan bikin penonton ikut tidak nyaman terus.'"],answer:1,explain:"S-B-I membuat umpan balik konkret & tidak menuduh: fakta situasi, perilaku yang teramati, dampak nyata.",hint:"Situasi + perilaku + dampak, atau label?"},
{n:23,type:"mcq",micro:"'Sandwich' umpan balik",q:"Menyelipkan kritik di antara dua pujian ('roti lapis') bisa bermasalah kalau...",options:["Efektif tanpa kelemahan, sehingga cocok dipakai kepada siapa saja dalam segala keadaan, bahkan saat orang sedang marah","Membuat kritiknya hilang sehingga yang menerima tak sadar ada yang perlu diperbaiki dalam pekerjaannya","Pujiannya jadi terasa tidak tulus & orang hanya menunggu 'tapi'-nya; lebih baik jujur & langsung dengan nada baik"],answer:2,explain:"Pujian tulus + kritik jelas + dukungan lebih baik daripada rumus kaku yang membuat orang curiga pada setiap pujian.",hint:"Rumus kaku bisa terasa palsu, atau selalu efektif?"},
{n:24,type:"mcq",micro:"Umpan balik satu-dua hal",q:"Memberi 10 poin kritik sekaligus biasanya...",options:["Membuat orang kewalahan & tidak tahu mulai dari mana; lebih baik pilih 1-3 yang terpenting","Paling membantu karena daftarnya lengkap, jadi semua bisa diperbaiki sekaligus","Menunjukkan kamu teliti dan berpengetahuan luas, sehingga orang lain menghormati penilaianmu"],answer:0,explain:"Umpan balik yang bisa dikerjakan adalah yang terfokus. Simpan sisanya untuk putaran berikutnya.",hint:"Fokus 1-3 hal, atau borong 10?"},
{n:25,type:"mcq",micro:"Menerima kritik yang disampaikan kasar",q:"Seseorang mengkritikmu dengan nada kasar. Cara menyaring:",options:["Percaya semua isi kritik itu dan mulai membenci dirimu sendiri, karena orang yang mengkritik keras benar tentang kamu sepenuhnya, lalu berubah total","Pisahkan isi yang mungkin benar dari cara penyampaian yang menyakitkan; ambil yang berguna, & kamu boleh menyampaikan bahwa nadanya kurang enak","Tolak semuanya mentah-mentah karena disampaikan dengan buruk, sebab kritik yang kasar tak ada isinya yang bermanfaat untukmu, lalu tak membahasnya lagi"],answer:1,explain:"'Cara kamu ngomong tadi kurang enak buatku, tapi poin soal tenggat aku terima & akan perbaiki.'",hint:"Pisahkan isi dari nada, atau tolak / telan semua?"},
{n:26,type:"mcq",micro:"Umpan balik & niat baik",q:"Saat menerima umpan balik, mengasumsikan niat baik si pemberi (kecuali ada bukti sebaliknya) membantu karena...",options:["Membuatmu mudah dibohongi oleh orang yang memuji berlebihan","Tidak ada gunanya karena kamu tetap akan membela diri dulu","Kamu jadi lebih terbuka mendengar & tidak buru-buru defensif"],answer:2,explain:"Kebanyakan umpan balik, meski canggung, berasal dari keinginan membantu. Membaca niat baik membuka pintu belajar.",hint:"Terbuka mendengar, atau langsung curiga?"},
{n:27,type:"tf",micro:"Umpan balik tentang perilaku, bukan pribadi",q:"Benar atau Salah: Umpan balik yang menyerang sifat pribadi seseorang ('kamu memang malas') lebih sulit dipakai untuk berubah daripada umpan balik tentang perilaku spesifik ('tugas kemarin dikumpulkan terlambat').",answer:true,explain:"Perilaku bisa diubah; label pribadi terasa sebagai vonis & memicu pertahanan.",hint:"Label pribadi lebih sulit dipakai, atau lebih mudah?"},
{n:28,type:"tf",micro:"Diam berarti tidak ada masalah?",q:"Benar atau Salah: Kalau kamu tidak pernah memberi umpan balik kepada anggota tim yang bekerja kurang baik, ia pasti akan menyadari sendiri & memperbaikinya.",answer:false,explain:"Sebaliknya, tanpa umpan balik yang jelas, orang sering tidak sadar ada masalah, atau mengira semuanya baik-baik saja. Diam bukan kebaikan.",hint:"Orang menyadari sendiri, atau butuh diberi tahu?"},
{n:29,type:"mcq",micro:"Umpan balik yang meminta, bukan memberi",q:"Kadang cara terbaik membantu adalah bertanya, bukan menyuruh. Contoh:",options:["'Menurutmu, bagian mana dari presentasi ini yang paling kamu ragukan?'","'Ubah semuanya, ini nggak bener dan harus diulang dari awal.'","'Pokoknya salah, nanti kamu pikirkan sendiri bagian yang mana.'"],answer:0,explain:"Pertanyaan reflektif membantu orang menemukan sendiri area perbaikan, yang lebih melekat daripada disuruh.",hint:"Bertanya reflektif, atau memerintah?"},
{n:30,type:"order",micro:"Menerima umpan balik dengan baik",q:"Urutkan langkah menerima umpan balik.",items:["Dengarkan sepenuhnya tanpa memotong atau membela diri","Ajukan pertanyaan klarifikasi bila ada yang belum jelas: 'Bisa kasih contoh?'","Ucapkan terima kasih atas masukannya","Setelah tenang, pilah: mana yang akan kamu terapkan & mengapa"],answer:[0,1,2,3],explain:"Dengar → klarifikasi → terima kasih → pilah nanti. Memutuskan saat masih defensif sering keliru.",hint:"Kapan kamu memilah mana yang dipakai — saat mendengar atau setelah tenang?"},
{n:31,type:"mcq",micro:"Umpan balik antar teman sebaya",q:"Memberi umpan balik ke teman (bukan bawahan/atasan) tetap perlu...",options:["Menghindari kritik demi persahabatan, sehingga temanmu tak tahu bagian yang kurang","Kerendahan hati ('ini menurutku, bisa jadi aku keliru') & menghormati bahwa itu karyanya","Nada memerintah dan tegas karena kalian setara, sehingga ia harus menuruti saranmu"],answer:1,explain:"Kesetaraan justru menuntut kehati-hatian: sampaikan sebagai pandangan, bukan vonis.",hint:"Rendah hati + hormat, atau memerintah / menghindar?"},
{n:32,type:"tf",micro:"Umpan balik positif membuat sombong?",q:"Benar atau Salah: Memberi umpan balik positif yang spesifik & tulus umumnya membuat orang malas atau sombong, jadi sebaiknya dihindari.",answer:false,explain:"Sebaliknya, umpan balik positif yang spesifik membantu orang tahu apa yang harus dipertahankan & meningkatkan semangat. Yang bermasalah hanya pujian kosong berlebihan yang tidak tulus.",hint:"Pujian spesifik & tulus = bikin malas, atau membantu?"},
{n:33,type:"mcq",micro:"Menerima umpan balik yang kamu tidak setujui",q:"Kamu benar-benar tidak setuju dengan sebuah masukan. Respons dewasa:",options:["'Kamu salah total, ngerti apa sih kamu soal ini? Aku lebih paham, jangan sok tahu deh.'","Mengangguk pura-pura setuju lalu mengabaikan semuanya dan diam-diam kesal kepada pemberi masukan","'Terima kasih, aku akan memikirkannya. Aku melihatnya agak berbeda karena X, tapi aku terbuka.'"],answer:2,explain:"Kamu boleh tidak setuju dengan tenang & jujur, tanpa menyerang atau berpura-pura setuju.",hint:"Tidak setuju dengan tenang, atau menyerang / pura-pura?"},
{n:34,type:"mcq",micro:"Umpan balik & bukti",q:"Umpan balik yang didukung contoh nyata ('di menit ke-3 kamu bilang X, padahal datanya Y')...",options:["Lebih mudah dipahami & dipercaya daripada penilaian umum tanpa contoh","Terkesan mencari-cari kesalahan karena terlalu banyak contoh yang disebut","Berlebihan karena contoh membuat penilaian terdengar lebih kasar dari aslinya"],answer:0,explain:"Contoh membuat umpan balik konkret & sulit disalahpahami. 'Kamu selalu ngawur' tanpa contoh mudah ditolak.",hint:"Didukung contoh, atau penilaian umum?"},
{n:35,type:"mcq",micro:"Menahan umpan balik saat marah",q:"Kamu kesal pada hasil kerja teman. Sebaiknya...",options:["Pendam saja kekesalan itu & bersikap dingin kepada orang tersebut, sampai ia sendiri menyadari apa kesalahannya","Tenangkan diri dulu, lalu sampaikan umpan balik secara faktual — bukan melampiaskan kemarahan sebagai 'umpan balik'","Sampaikan sekarang juga selagi masih panas, supaya terdengar paling 'jujur' & semua kekesalanmu bisa keluar sepenuhnya"],answer:1,explain:"Umpan balik yang keluar dari kemarahan cenderung menyerang pribadi & merusak. Tenang dulu, faktakan.",hint:"Tenang lalu faktakan, atau lampiaskan / pendam?"},
{n:36,type:"mcq",micro:"Umpan balik yang menyeimbangkan kejujuran & kebaikan",q:"Prinsip 'jujur tapi peduli' dalam umpan balik berarti...",options:["Memilih bersikap 'baik' dengan menyembunyikan masalah, supaya hubungan tidak terasa canggung","Memilih 'jujur' walau isinya menghina, karena kebenaran harus disampaikan tanpa memikirkan perasaan","Menyampaikan kebenaran yang perlu didengar, dengan cara yang menunjukkan kamu menghargai orangnya"],answer:2,explain:"Peduli tanpa jujur = menyesatkan. Jujur tanpa peduli = melukai. Umpan balik terbaik menggabung keduanya.",hint:"Jujur + peduli, atau salah satu saja?"},
{n:37,type:"tf",micro:"Meminta umpan balik itu kekuatan",q:"Benar atau Salah: Aktif meminta umpan balik ('menurutmu apa yang bisa aku perbaiki?') menunjukkan kamu tidak percaya diri & tidak mampu menilai kerjamu sendiri.",answer:false,explain:"Sebaliknya, meminta umpan balik menunjukkan kamu serius ingin berkembang. Orang yang memintanya biasanya maju lebih cepat karena mendapat informasi yang orang lain tahan.",hint:"Meminta umpan balik = lemah, atau serius berkembang?"},
{n:38,type:"mcq",micro:"Umpan balik lisan vs tertulis",q:"Untuk masukan yang cukup sensitif, sering lebih baik...",options:["Disampaikan lisan/langsung sehingga nada & niat terbaca & bisa berdiskusi, bukan lewat pesan singkat yang mudah salah tafsir","Lewat teks agar ada bukti tertulis dan tidak terjadi salah ingat di kemudian hari antara kedua pihak yang terlibat","Lewat orang ketiga yang dipercaya kedua pihak, supaya tidak terjadi pertengkaran langsung di antara mereka berdua"],answer:0,explain:"Teks kehilangan nada; masukan sensitif lewat teks mudah terasa dingin atau menyerang. Tatap muka lebih aman.",hint:"Langsung agar nada terbaca, atau teks / orang ketiga?"},
{n:39,type:"mcq",micro:"Umpan balik & tindak lanjut",q:"Setelah menerima umpan balik & mencoba memperbaikinya, langkah yang baik:",options:["Menganggap umpan balik selesai setelah didengar, tanpa menunjukkan hasilnya","Kembali ke pemberi: 'Aku sudah coba ubah bagian itu, menurutmu sekarang gimana?'","Tak menunjukkan perubahan yang sudah dibuat, karena pemberi masukan akan menyadarinya sendiri"],answer:1,explain:"Menutup lingkaran (menunjukkan kamu menindaklanjuti) menghargai si pemberi & mempercepat perbaikan lebih lanjut.",hint:"Tunjukkan hasil perbaikan, atau abaikan?"},
{n:40,type:"open",micro:"Memperbaiki umpan balik buruk",q:"Ubah 3 umpan balik buruk ini menjadi umpan balik yang membangun, jelaskan perbaikannya: (a) 'Laporanmu jelek.' (b) 'Kamu nggak niat ya bikinnya?' (c) 'Semuanya salah, ulang.'",explain:"Jawaban baik mengubah tiap umpan balik menjadi: spesifik (bagian mana), fokus pada hasil/perilaku (bukan pribadi/niat), disertai alasan + saran konkret, tidak melebih-lebihkan, dan menyebut apa yang sudah baik / masih bisa dipakai — dengan penjelasan tiap perbaikan.",hint:"Ganti label ('jelek') & tuduhan niat dengan bagian spesifik + alasan + saran; jangan melebih-lebihkan.",sample:"(a) 'Laporanmu jelek' → 'Isi datamu lengkap, tapi laporannya sulit diikuti karena tidak ada sub-judul dan paragrafnya sangat panjang. Coba tambahkan judul tiap bagian dan pecah paragraf besar.' Perbaikan: menyebut kekuatan, menunjuk masalah spesifik (struktur), memberi saran konkret, membuang kata 'jelek' yang tidak informatif. (b) 'Kamu nggak niat ya?' → 'Beberapa bagian terasa terburu-buru — ada 3 grafik tanpa keterangan dan kesimpulannya cuma satu kalimat. Kalau dilengkapi, ini bisa jauh lebih kuat.' Perbaikan: mengganti tuduhan tentang niat/pribadi dengan pengamatan atas hasil yang bisa diperbaiki. (c) 'Semuanya salah, ulang' → 'Pendekatan dasarmu di bagian metode belum sesuai instruksi — di sini seharusnya memakai data primer, bukan sekunder. Kalau bagian itu diperbaiki, sebagian besar analisismu masih bisa dipakai.' Perbaikan: spesifik tentang apa yang salah dan kenapa, tidak melebih-lebihkan ('semuanya'), dan menunjukkan apa yang masih bisa diselamatkan."},
{n:41,type:"mcq",micro:"Skenario: teman minta pendapat jujur",q:"Teman menunjukkan puisi buatannya & minta pendapat jujur. Menurutmu bagian tengahnya lemah. Respons:",options:["'Bagus semua! Tak ada bagian yang perlu diubah, puisimu sudah sempurna dari bait pertama sampai terakhir!' (padahal bohong supaya ia senang)","'Bagian tengahnya jelek banget & membosankan, ganti saja semuanya, nanti baru tunjukkan lagi kalau sudah kamu perbaiki sampai bagus.'","'Bait pertamamu kuat, imajinya jelas. Bait kedua menurutku agak umum — mungkin bisa dikasih detail yang lebih spesifik seperti bait pertama?'"],answer:2,explain:"Sebut kekuatan spesifik → area yang bisa dikuatkan → saran yang mengacu ke kekuatannya sendiri.",hint:"Kekuatan + saran spesifik, atau bohong / satu kata negatif?"},
{n:42,type:"mcq",micro:"Skenario: menerima nilai & komentar guru",q:"Guru memberi nilai rendah dengan komentar 'analisis kurang dalam'. Langkah yang produktif:",options:["Menemui guru: 'Bu, boleh minta contoh bagian mana yang analisisnya kurang dalam & seperti apa yang lebih dalam?'","Kesal lalu menyimpulkan guru itu tidak adil dan pilih kasih, sehingga tak perlu bertanya lagi, lalu mengerjakan hal lain","Mengabaikan komentar itu dan menganggap nilainya hanya soal selera guru, lalu mengerjakan tugas berikutnya sama saja"],answer:0,explain:"Meminta contoh spesifik mengubah komentar umum menjadi arahan yang bisa kamu pakai untuk tugas berikutnya.",hint:"Minta contoh spesifik, atau kesal / abaikan?"},
{n:43,type:"mcq",micro:"Skenario: memberi umpan balik ke kakak kelas",q:"Kakak kelas yang memimpin latihan melakukan sesuatu yang menurutmu kurang efektif. Cara menyampaikan dengan hormat:",options:["Mengkritiknya langsung di depan peserta latihan supaya semua tahu caranya kurang efektif di lapangan","'Kak, boleh usul? Menurutku kalau pemanasan dipisah per kelompok, antreannya lebih cepat. Gimana?'","Diam saja karena ia lebih senior, lalu mengeluh tentangnya kepada teman sesudah latihan"],answer:1,explain:"Umpan balik ke atas: minta izin, sampaikan sebagai usul + alasan, nada hormat, tanya pendapatnya.",hint:"Usul hormat + alasan, atau diam / kritik terbuka?"},
{n:44,type:"mcq",micro:"Skenario: umpan balik kelompok",q:"Dalam sesi umpan balik kelompok atas draf poster, cara agar bermanfaat:",options:["Anggota berbicara sekaligus sambil melempar kritik acak, sehingga pembuat poster mendengar sebanyak mungkin masukan","Hanya memuji tanpa memberi saran agar tak seorang pun tersinggung dan suasana menyenangkan","Tiap orang sebut satu hal yang kuat & satu saran spesifik; pembuat mencatat & bertanya bila perlu"],answer:2,explain:"Struktur (satu kekuatan + satu saran per orang) menjaga sesi tetap fokus & seimbang.",hint:"Terstruktur & seimbang, atau lempar kritik acak / hanya memuji?"},
{n:45,type:"order",micro:"Sesi umpan balik draf tulisan",q:"Urutkan cara menjalankan sesi umpan balik atas draf tulisan teman.",items:["Penulis menyebut apa yang ia inginkan masukannya ('tolong cek bagian argumen')","Pembaca menyampaikan kesan umum & bagian yang kuat","Pembaca memberi 2-3 saran spesifik dengan alasan","Penulis bertanya balik & menyimpulkan langkah revisinya"],answer:[0,1,2,3],explain:"Penulis mengarahkan → kesan & kekuatan → saran spesifik → penulis menyimpulkan. Fokus pada yang penulis butuhkan.",hint:"Siapa yang menentukan fokus sesi — penulis atau pembaca?"},
{n:46,type:"mcq",micro:"Skenario: umpan balik menyakitkan tapi benar",q:"Seseorang menunjukkan bahwa kamu sering memotong pembicaraan orang. Kamu tersinggung tapi sadar itu benar. Respons terbaik:",options:["'Aku sempat kaget dengernya, tapi setelah kupikir kamu benar. Makasih sudah bilang, aku akan lebih perhatikan.'","'Nggak kok, kamu juga sering motong omongan orang!' lalu menunjuk kesalahan orang itu supaya impas juga","Menghindari orang itu sejak saat itu supaya kamu tidak perlu lagi mendengar kritik darinya tentang caramu berbicara"],answer:0,explain:"Mengakui umpan balik yang benar (meski menyakitkan) adalah tanda kedewasaan & mempercepat perbaikan.",hint:"Akui & berterima kasih, atau membalas / menghindar?"},
{n:47,type:"mcq",micro:"Skenario: umpan balik ke adik",q:"Adikmu menunjukkan PR-nya yang banyak salah. Cara memberi umpan balik yang tidak mematahkan semangat:",options:["Mengerjakan ulang semua soal itu untuknya sampai selesai, supaya hasilnya benar semua & ia bisa langsung mengumpulkannya ke guru besok pagi","'Nomor 1 sampai 4 caranya sudah benar, bagus. Nomor 5-8 kayaknya ada yang keliru di langkah pembagian — coba kita lihat nomor 5 bareng.'","'Banyak banget yang salah nih, kamu nggak belajar ya? Pantas saja nilaimu jelek terus, bikin malu keluarga saja kamu ini.'"],answer:1,explain:"Sebut yang benar dulu → tunjuk pola kesalahan → dampingi memperbaiki satu, bukan mengambil alih.",hint:"Yang benar dulu + dampingi, atau menyalahkan / ambil alih?"},
{n:48,type:"mcq",micro:"Skenario: diminta menilai lomba antar teman",q:"Kamu juri lomba kelas & harus memberi umpan balik ke peserta yang kalah. Cara yang adil & membangun:",options:["'Kamu kalah karena karyamu jelek, makanya tidak menang, jadi tidak usah dibahas lagi dan sudahlah.'","Menghindar dan tidak memberi penjelasan kepada peserta yang kalah, supaya tak ada yang bertanya-tanya lagi nanti","Sebut kriteria penilaian, tunjukkan di mana ia kuat & di mana selisihnya dengan pemenang, beri saran untuk lain kali"],answer:2,explain:"Umpan balik berbasis kriteria yang jelas terasa adil & membantu peserta memperbaiki diri.",hint:"Berbasis kriteria + saran, atau vonis / menghindar?"},
{n:49,type:"mcq",micro:"Skenario: umpan balik yang bertentangan",q:"Dua orang memberi umpan balik yang bertentangan (satu bilang terlalu panjang, satu bilang terlalu singkat). Sikap:",options:["Pertimbangkan konteks & tujuanmu, cari pola dari lebih banyak masukan, & putuskan sendiri — umpan balik adalah masukan, bukan perintah mutlak","Bingung lalu tidak mengubah apa-apa, karena dua masukan yang saling bertentangan tidak bisa dipakai, jadi biarkan saja seperti semula","Menuruti masukan orang yang berbicara paling akhir, karena itu yang paling baru, relevan, dan benar untuk karyamu sekarang"],answer:0,explain:"Umpan balik yang bertentangan wajar. Kamu pemilik keputusan; timbang berdasarkan tujuan & pola.",hint:"Timbang & putuskan sendiri, atau bingung / ikut yang terakhir?"},
{n:50,type:"open",micro:"Merancang cara meminta umpan balik",q:"Kamu akan mengikuti audisi paduan suara dan ingin berkembang cepat. Rancang bagaimana kamu akan MEMINTA umpan balik yang berguna: dari siapa, pertanyaan spesifik apa yang kamu ajukan, dan apa yang akan kamu lakukan setelah menerimanya.",explain:"Jawaban baik menyebut: sumber yang tepat & beragam (ahli, rekan berpengalaman, rekaman diri), pertanyaan spesifik yang bisa dijawab (bukan 'gimana tadi'), dan tindak lanjut yang fokus (pilih 1-2 hal terpenting, latih, lalu kembali menunjukkan hasil untuk menutup lingkaran) plus berterima kasih.",hint:"Pilih sumber yang tepat, ajukan pertanyaan spesifik, lalu fokus perbaiki 1-2 hal & tunjukkan hasilnya kembali.",sample:"Dari siapa: (1) pelatih/guru musik — karena ia paling tahu teknik; (2) satu-dua anggota paduan suara yang berpengalaman — untuk sudut pandang 'dari dalam'; (3) merekam suaraku sendiri untuk umpan balik mandiri. Pertanyaan spesifik yang kuajukan (bukan 'gimana tadi?'): 'Bagian mana yang nada atau ketukannya paling sering meleset?', 'Apakah volume dan pengucapan liriknya sudah jelas terdengar?', 'Satu hal apa yang kalau kuperbaiki paling besar pengaruhnya?'. Setelah menerima: aku mencatat poinnya, memilih 1-2 yang paling sering disebut atau paling berdampak untuk dilatih dulu (bukan semuanya sekaligus), berlatih fokus pada itu selama seminggu, lalu kembali menyanyikan bagian yang sama ke pelatih dan bertanya 'menurut Bapak/Ibu, sekarang bagaimana?' untuk menutup lingkaran. Aku juga berterima kasih ke tiap orang yang memberi masukan supaya mereka nyaman jujur lagi."},
{n:51,type:"mcq",micro:"Skenario: umpan balik untuk sesuatu yang sudah selesai/tak bisa diubah",q:"Acara sudah lewat & kamu punya kritik. Cara yang tetap berguna:",options:["Diam saja padahal ada pelajaran penting yang bisa diambil, karena acaranya sudah lewat & tidak bisa diulang lagi","Sampaikan sebagai pelajaran untuk acara berikutnya: 'Buat lain kali, mungkin briefing panitianya perlu lebih awal.'","Terus-menerus menyalahkan hal yang sudah lewat dalam setiap pertemuan sampai orang lain bosan mendengarnya"],answer:1,explain:"Umpan balik atas hal yang tak bisa diubah tetap berguna bila diarahkan ke masa depan, bukan menyalahkan masa lalu.",hint:"Arahkan ke perbaikan berikutnya, atau salahkan masa lalu / diam?"},
{n:52,type:"tf",micro:"Umpan balik butuh izin/konteks",q:"Benar atau Salah: Memberi kritik yang tidak diminta kepada orang yang sedang bangga menunjukkan karyanya, tanpa membaca situasi, bisa terasa melukai meski niatmu membantu.",answer:true,explain:"Membaca kesiapan orang & bertanya dulu ('mau masukan atau mau aku ikut senang dulu?') membuat umpan balik lebih diterima.",hint:"Kritik tak diminta selalu diterima, atau perlu membaca situasi?"},
{n:53,type:"mcq",micro:"Skenario: umpan balik berulang tak ditindaklanjuti",q:"Kamu sudah beberapa kali memberi masukan yang sama ke teman kelompok tapi tidak ada perubahan. Langkah berikutnya:",options:["Terus mengulang masukan yang sama persis dengan nada yang makin kesal & makin keras setiap kali pertemuan kelompok","Menyerah lalu mengerjakan bagiannya diam-diam sambil kesal dan tak membicarakan masalah itu lagi dengannya, demi menjaga suasana","Bicara lebih langsung tentang polanya & dampaknya ke tim, tanyakan apa kendalanya, & sepakati langkah konkret + cara mengeceknya"],answer:2,explain:"Kalau masukan halus berulang gagal, naikkan kejelasan: bicarakan polanya, gali kendala, buat kesepakatan yang terukur.",hint:"Naikkan kejelasan + gali kendala + sepakati, atau ulang kesal / menyerah?"},
{n:54,type:"mcq",micro:"Skenario: memberi umpan balik positif yang tulus",q:"Anggota tim yang pendiam diam-diam menyelesaikan bagian tersulit dengan sangat baik. Umpan balik yang menguatkan:",options:["'Bagian analisis statistik yang kamu kerjakan itu rapi & tepat — itu bagian tersulit & kamu menyelesaikannya dengan bagus. Terima kasih.'","Tidak berkata apa-apa karena 'itu memang tugasnya' dan sudah seharusnya ia kerjakan dengan baik tanpa dipuji oleh tim","'Lumayan lah, tapi masih banyak bagian lain yang lebih penting daripada analisis itu, kerjakan bagian itu dulu ya teman.'"],answer:0,explain:"Umpan balik positif spesifik ke orang yang jarang disorot sangat berarti & mendorong kontribusi berikutnya.",hint:"Spesifik + tulus + berterima kasih, atau diam / datar?"},
{n:55,type:"mcq",micro:"Skenario: menerima umpan balik dari banyak orang sekaligus",q:"Di sesi kelompok, kamu menerima banyak masukan sekaligus & mulai kewalahan. Sikap:",options:["Menutup diri dan tak mengerjakan revisi karena merasa masukan hanya menjatuhkan hasil kerjamu, lalu pergi","'Makasih semua. Banyak masukan bagus — boleh aku catat dulu & aku olah, nanti aku kabari langkah revisiku?'","Membela tiap poin satu per satu saat itu juga, supaya orang tahu alasan di balik setiap pilihanmu"],answer:1,explain:"Kamu boleh meminta waktu untuk memproses. Tidak semua harus dijawab atau diputuskan saat itu juga.",hint:"Minta waktu memproses, atau membela semua / menutup diri?"},
{n:56,type:"mcq",micro:"Skenario: umpan balik yang bikin kamu ragu total",q:"Satu masukan keras membuatmu ingin membuang seluruh karyamu. Sikap yang seimbang:",options:["Buang semua karyamu lalu mulai dari nol, karena satu masukan keras menunjukkan seluruh hasilnya buruk dan tak bisa diperbaiki, demi hasil lebih baik","Abaikan sepenuhnya masukan itu dan jangan ubah apa-apa, karena orang yang mengkritik sekeras itu hanya iri atau ingin menjatuhkanmu","Satu masukan bukan vonis atas seluruh karya; cari pendapat lain, lihat mana bagian spesifik yang dimaksud, & perbaiki bagian itu — bukan membuang semua"],answer:2,explain:"Reaksi 'semuanya jelek' biasanya emosi, bukan penilaian. Persempit ke bagian spesifik & tanggapi itu.",hint:"Persempit ke bagian spesifik, atau buang semua / abaikan semua?"},
{n:57,type:"tf",micro:"Menutup lingkaran umpan balik",q:"Benar atau Salah: Setelah menerima umpan balik, tidak perlu memberi tahu si pemberi apa yang akhirnya kamu putuskan — itu urusanmu sendiri & tidak memengaruhi apa pun.",answer:false,explain:"Sebaliknya, orang berhenti memberi umpan balik kalau merasa masukannya masuk ke ruang hampa. Menutup lingkaran (mengabari keputusanmu, meski tak menuruti semua) menjaga saluran tetap terbuka.",hint:"Kabari keputusanmu, atau diamkan saja?"},
{n:58,type:"mcq",micro:"Skenario: umpan balik & perasaan pemberi",q:"Teman memberimu masukan dengan hati-hati & terlihat khawatir kamu tersinggung. Respons yang menjaga hubungan:",options:["'Makasih ya udah berani ngomong. Aku nggak tersinggung kok, ini justru membantu.'","Diam dingin dan tidak menanggapi sehingga ia menyesal sudah bicara","'Ya ampun, sensitif banget sih kamu ngomongnya, aku kan cuma dengar, nggak usah hati-hati.'"],answer:0,explain:"Menghargai keberanian si pemberi membuat budaya umpan balik yang aman tumbuh di antara kalian.",hint:"Hargai keberaniannya, atau bikin ia menyesal?"},
{n:59,type:"mcq",micro:"Skenario: kamu diminta memberi umpan balik anonim",q:"Formulir umpan balik anonim untuk kegiatan sekolah. Cara mengisinya dengan bertanggung jawab:",options:["Menulis 'bagus' saja tanpa isi, karena penulisnya tak diketahui dan tak perlu susah payah","Tetap spesifik, sopan, & berorientasi perbaikan — anonim bukan alasan untuk kasar","Menulis hinaan dan kata kasar karena toh tak ketahuan siapa penulisnya, jadi tak ada konsekuensi"],answer:1,explain:"Anonimitas menghilangkan nama, bukan tanggung jawab. Umpan balik yang berguna tetap spesifik & sopan.",hint:"Spesifik & sopan, atau kasar karena anonim / kosong?"},
{n:60,type:"open",micro:"Skenario menyeluruh",q:"Kamu memimpin proyek dan perlu memberi umpan balik ke tiga anggota: A (kerjanya bagus tapi sering telat), B (rajin tapi hasilnya asal-asalan), C (bekerja baik & tepat waktu). Rancang umpan balik singkat untuk masing-masing dan jelaskan prinsip yang kamu pakai.",explain:"Jawaban baik memberi umpan balik berbeda & tepat sasaran untuk tiap anggota (A: akui kualitas + minta perbaiki ketepatan waktu dengan langkah konkret; B: akui usaha + minta perbaiki kualitas dengan alat bantu; C: umpan balik positif spesifik agar dipertahankan) dan menyebut prinsip: kekuatan dulu, fokus perilaku bukan pribadi, saran konkret & terukur, disampaikan pribadi, nada mendukung.",hint:"Beda orang, beda pesan; selalu kekuatan dulu (termasuk untuk C), fokus perilaku, saran konkret & terukur, pribadi, mendukung.",sample:"Untuk A: 'Kualitas riset kamu bagus banget dan itu ngangkat proyek kita. Satu hal: beberapa bagianmu masuk mendekati tenggat, jadi tim jadi buru-buru di akhir. Bisa kita sepakati kamu kirim draf dua hari sebelum tenggat? Kalau ada kendala, kabari lebih awal ya.' Untuk B: 'Aku hargai kamu selalu ambil bagian dan nggak pernah menghindar. Tapi di bagian terakhir ada beberapa data yang belum dicek dan format yang belum sesuai. Menurutku kalau kamu luangkan waktu ekstra buat mengecek sebelum kirim, hasilnya bisa sekuat usahamu. Mau kita buat checklist singkat bareng?' Untuk C: 'Kamu kerja bagus dan selalu tepat waktu — itu bikin bagian tim yang lain jadi lebih ringan. Terima kasih, tolong dipertahankan.' Prinsip yang kupakai: (1) selalu sebut kekuatan spesifik lebih dulu, termasuk ke C yang tidak punya masalah — umpan balik positif juga penting; (2) fokus pada perilaku/hasil yang bisa diubah (telat, belum dicek), bukan label pribadi ('kamu pemalas'); (3) tiap saran disertai langkah konkret & terukur (kirim 2 hari lebih awal, buat checklist); (4) sampaikan berdua/pribadi, bukan di grup; (5) tutup dengan tawaran bantuan & nada 'aku di pihak kalian'."},
{n:61,type:"mcq",micro:"Mengapa umpan balik spesifik lebih baik",q:"Mengapa 'paragraf 3 kalimatnya terlalu panjang' lebih berguna daripada 'tulisanmu kurang jelas'?",options:["Ia lebih sopan karena memakai kata-kata halus yang menyenangkan hati penerimanya","Ia lebih pendek karena hanya menyebut satu kata penilaian untuk seluruh karya","Ia menunjuk persis apa yang harus diubah, jadi orang tahu tindakan yang harus diambil"],answer:2,explain:"Umpan balik yang bisa ditindaklanjuti menjawab 'jadi apa yang harus aku lakukan?'. Yang umum tidak.",hint:"Menunjuk tindakan yang jelas, atau sekadar lebih sopan?"},
{n:62,type:"mcq",micro:"Mengapa menyerang pribadi gagal",q:"Mengapa umpan balik yang menyerang pribadi ('kamu bodoh') hampir selalu gagal membuat orang berubah?",options:["Ia memicu pertahanan diri & rasa malu, sehingga orang menutup telinga & tidak ada arah perbaikan yang jelas","Ia terlalu jujur sehingga orang takut mendengarnya, & ketakutan itulah yang membuat mereka tidak mau berubah","Ia sebenarnya sangat efektif, karena rasa malu & marah yang muncul membuat orang langsung berubah jadi lebih baik"],answer:0,explain:"Otak yang merasa diserang beralih ke bertahan, bukan belajar. Fokus pada perilaku menjaga mode belajar tetap menyala.",hint:"Memicu pertahanan & tanpa arah, atau efektif?"},
{n:63,type:"tf",micro:"Umpan balik dua arah",q:"Benar atau Salah: Hubungan atau tim yang sehat biasanya punya umpan balik yang mengalir dua arah — bukan hanya dari 'atas ke bawah'.",answer:true,explain:"Ketika anggota juga bisa memberi masukan ke pemimpin, keputusan jadi lebih baik & orang merasa dihargai.",hint:"Dua arah, atau hanya dari atas?"},
{n:64,type:"mcq",micro:"Bias saat menerima umpan balik",q:"Kecenderungan umum yang membuat orang sulit menerima umpan balik:",options:["Tidak ada bias dalam cara orang menerima kritik; orang menilai masukan secara netral, seimbang, dan tak merasa terancam, bahkan saat dikritik di depan umum","Menganggap kritik atas suatu perilaku sebagai serangan atas seluruh diri; ingin membuktikan diri benar; mengingat kritik lebih kuat daripada pujian","Terlalu mudah menerima semua masukan dari siapa saja tanpa memilah, sehingga orang tidak punya pendirian & cepat berubah-ubah arah"],answer:1,explain:"Menyadari bias ini ('ini soal satu bagian, bukan seluruh aku') membantu mendengar lebih jernih.",hint:"Ada kecenderungan yang menghalangi, atau tidak ada?"},
{n:65,type:"mcq",micro:"Mengapa 'sandwich' bisa gagal",q:"Kelemahan utama rumus 'pujian-kritik-pujian' yang kaku:",options:["Membuat orang menangis karena kritik di tengah terasa menyakitkan, meski dibungkus pujian di kedua sisi","Membuat umpan balik terlalu jujur sehingga orang tak sanggup mendengar kebenarannya dengan tenang dan terbuka","Orang belajar mengabaikan pujian & hanya menunggu bagian 'tapi', sehingga pujian tulus kehilangan nilainya"],answer:2,explain:"Lebih baik: pujian tulus ketika memang ada, kritik jelas ketika perlu, tanpa rumus yang memaksa.",hint:"Pujian kehilangan nilai, atau selalu berhasil?"},
{n:66,type:"tf",micro:"Umpan balik = fakta mutlak?",q:"Benar atau Salah: Umpan balik yang kamu terima selalu merupakan gambaran objektif & lengkap tentang kualitas kerjamu.",answer:false,explain:"Sebaliknya, umpan balik adalah satu sudut pandang, dipengaruhi selera, pengalaman, & suasana hati si pemberi. Cari pola dari beberapa sumber & timbang dengan tujuanmu.",hint:"Kebenaran mutlak, atau satu sudut pandang?"},
{n:67,type:"mcq",micro:"Umpan balik & pertumbuhan",q:"Orang yang berkembang paling cepat dalam suatu keterampilan biasanya...",options:["Aktif mencari umpan balik spesifik & benar-benar menerapkannya, lalu mengeceknya lagi","Menghindari umpan balik agar tak kecewa, dan berlatih sendirian sampai merasa sudah cukup baik","Hanya menerima pujian dari orang yang menyukainya, karena kritik memperlambat belajar"],answer:0,explain:"Latihan tanpa umpan balik sering mengulang kesalahan yang sama. Umpan balik + penerapan = 'latihan terarah'.",hint:"Cari & terapkan umpan balik, atau hindari?"},
{n:68,type:"mcq",micro:"Menilai apakah suatu umpan balik layak diterapkan",q:"Cara memutuskan apakah akan menuruti sebuah masukan:",options:["Abaikan masukan yang terasa tidak enak di hati, karena masukan yang baik biasanya menyenangkan dan terdengar manis saat didengar oleh telinga","Cek: apakah sesuai tujuanku? apakah orang lain menyebut hal serupa? apakah pemberinya paham konteksnya? apakah manfaatnya sepadan dengan usahanya?","Turuti masukan dari siapa saja tanpa memilah, karena orang lain lebih tahu daripada dirimu sendiri tentang karyamu, walau belum paham konteks"],answer:1,explain:"Umpan balik adalah data. Kamu tetap pemilik keputusan; timbang dengan tujuan, pola, & konteks.",hint:"Timbang dengan beberapa pertanyaan, atau turuti / abaikan semua?"},
{n:69,type:"mcq",micro:"Umpan balik & rasa aman psikologis",q:"Mengapa tim yang anggotanya takut memberi/menerima umpan balik sering berkinerja buruk?",options:["Karena mereka terlalu ramah satu sama lain, sehingga anggota sibuk menjaga perasaan dan tak sempat bekerja","Tidak ada hubungannya, karena kinerja tim hanya ditentukan oleh kemampuan masing-masing anggotanya","Masalah disembunyikan sampai terlambat, orang tidak belajar dari kesalahan, & kualitas menurun diam-diam"],answer:2,explain:"Rasa aman untuk berkata 'menurutku ini kurang tepat' adalah salah satu ciri tim berkinerja tinggi.",hint:"Masalah tersembunyi & tak ada belajar, atau terlalu ramah?"},
{n:70,type:"order",micro:"Dari defensif ke belajar",q:"Urutkan proses mengubah reaksi defensif menjadi sikap belajar saat menerima kritik.",items:["Kenali reaksi tubuh: panas, ingin membantah","Beri jeda: tarik napas, tahan respons cepat","Ingatkan diri: 'Ini soal satu bagian kerjaku, bukan seluruh nilai diriku'","Dengarkan sisanya & tanyakan contoh, putuskan tindak lanjut setelah tenang"],answer:[0,1,2,3],explain:"Kenali → jeda → bingkai ulang → dengar & tunda keputusan. Jeda memisahkan reaksi dari respons.",hint:"Apa yang perlu kamu sadari sebelum bisa memberi jeda?"},
{n:71,type:"mcq",micro:"Umpan balik positif juga butuh spesifik",q:"'Kerja bagus!' kurang berguna dibanding 'Cara kamu menyusun tabel perbandingan itu bikin datanya langsung kebaca' karena...",options:["Yang spesifik memberi tahu perilaku apa yang berhasil sehingga bisa diulang; 'kerja bagus' tidak","Yang spesifik lebih panjang & lebih rumit, sehingga orang butuh waktu lebih lama untuk membacanya sampai selesai","Pujian umum lebih tulus & lebih terdengar jujur daripada pujian yang terlalu rinci & dibuat-buat oleh pemberinya"],answer:0,explain:"Pujian spesifik = umpan balik yang mengajarkan 'lakukan lebih banyak hal ini'.",hint:"Menunjuk perilaku yang berhasil, atau sekadar lebih panjang?"},
{n:72,type:"tf",micro:"Meminta umpan balik spesifik lebih efektif",q:"Benar atau Salah: Bertanya 'gimana menurutmu?' yang luas cenderung menghasilkan umpan balik yang lebih berguna daripada pertanyaan spesifik seperti 'bagian mana yang paling lemah & kenapa?'.",answer:false,explain:"Sebaliknya, pertanyaan luas mengundang jawaban sopan & kosong ('bagus kok'). Pertanyaan terarah mengundang jawaban yang bisa dipakai.",hint:"Pertanyaan terarah lebih berguna, atau sama saja?"},
{n:73,type:"mcq",micro:"Umpan balik & waktu terbaik",q:"Kenapa umpan balik yang datang jauh setelah kejadian sering kurang berguna?",options:["Umpan balik yang lama justru lebih akurat, karena pemberinya sudah punya banyak waktu untuk memikirkannya","Detail sudah kabur, kesempatan memperbaiki sudah lewat, & orang sulit menghubungkannya dengan tindakannya","Karena orang sudah lupa nama pemberi umpan balik itu, sehingga tak tahu harus berterima kasih ke siapa"],answer:1,explain:"Umpan balik paling manjur saat memori masih segar & masih ada kesempatan menerapkan.",hint:"Detail kabur & kesempatan lewat, atau lebih akurat?"},
{n:74,type:"mcq",micro:"Menyeimbangkan jumlah umpan balik",q:"Memberi terlalu banyak umpan balik sekaligus berisiko karena...",options:["Lebih baik daripada memberi sedikit, karena orang tahu semua kekurangannya sekaligus","Membuat orang terlalu percaya diri karena merasa sudah tahu semuanya","Orang kewalahan, tidak tahu prioritas, & akhirnya tidak memperbaiki apa pun"],answer:2,explain:"1-3 poin yang benar-benar diterapkan mengalahkan 15 poin yang membuat orang beku.",hint:"Kewalahan & tak ada aksi, atau selalu lebih baik?"},
{n:75,type:"tf",micro:"Umpan balik berlaku juga untuk hal baik",q:"Benar atau Salah: Kalau seseorang melakukan sesuatu dengan sangat baik & kamu tidak mengatakannya, kamu kehilangan kesempatan menguatkan perilaku yang kamu ingin ia ulangi.",answer:true,explain:"Diam atas hal baik membuat orang menebak apakah kontribusinya diperhatikan. Umpan balik positif menutup celah itu.",hint:"Diam atas hal baik = netral, atau kehilangan kesempatan?"},
{n:76,type:"mcq",micro:"Umpan balik ke orang yang lebih berkuasa",q:"Memberi umpan balik ke guru/pelatih/atasan lebih berhasil bila...",options:["Disampaikan sebagai pengamatan & usul dengan hormat, di waktu yang tepat, fokus pada dampak — bukan tuntutan atau kritik di depan umum","Tak dilakukan karena guru, pelatih, dan atasan sudah tahu yang terbaik dan tidak butuh masukan dari bawahan, sehingga hal itu dianggap kurang sopan","Disampaikan sekeras mungkin di depan umum dengan nada menuntut, agar mereka mendengar dan tak bisa mengabaikan keluhanmu lagi"],answer:0,explain:"Umpan balik 'ke atas' butuh ekstra kehati-hatian bentuk, tapi tetap sah & berharga.",hint:"Pengamatan + usul hormat, atau tuntutan keras / tidak sama sekali?"},
{n:77,type:"mcq",micro:"Umpan balik & identitas",q:"Kalimat pembuka 'Ini soal drafnya, bukan soal kemampuanmu secara keseluruhan' membantu karena...",options:["Membuat umpan balik jadi tidak jujur karena kamu sengaja menyembunyikan kelemahan pekerjaannya dari orang itu","Memisahkan kritik atas satu hasil dari penilaian atas diri orang, sehingga ia bisa mendengar tanpa merasa terancam","Menyembunyikan maksud sebenarnya dari kritikmu, sehingga orang itu tidak sadar bahwa ia sedang diberi masukan"],answer:1,explain:"Membingkai umpan balik sebagai 'tentang pekerjaan ini' menurunkan pertahanan & membuka ruang belajar.",hint:"Memisahkan hasil dari harga diri, atau menyembunyikan maksud?"},
{n:78,type:"mcq",micro:"Menilai umpan balik yang saling bertentangan",q:"Ketika umpan balik dari berbagai orang bertentangan, cara yang bijak:",options:["Ambil rata-rata dari semua masukan secara mekanis, lalu ubah karyamu persis di titik tengah, tanpa melihat siapa pemberinya","Turuti pendapat orang yang paling galak dan paling keras suaranya, karena ia paling mengerti, dan keputusan akhir ada padanya","Cari pola (apa yang disebut banyak orang), pertimbangkan siapa yang paling paham konteks & tujuanmu, & ingat keputusan akhir ada padamu"],answer:2,explain:"Umpan balik bukan pemungutan suara. Timbang kualitas & relevansi, bukan hanya jumlah.",hint:"Cari pola + timbang relevansi, atau rata-rata / ikut yang galak?"},
{n:79,type:"mcq",micro:"Umpan balik & budaya kelompok",q:"Kelompok bisa membangun budaya umpan balik yang sehat dengan...",options:["Menjadikannya rutin & normal (bukan hanya saat ada masalah), menyambut masukan dengan terima kasih, & fokus pada perbaikan bukan menyalahkan","Hanya memberi umpan balik saat sedang marah atau kecewa, supaya orang lain tahu bahwa masalahnya benar-benar serius","Melarang semua bentuk kritik di dalam kelompok demi menjaga kekompakan & menghindari perasaan tersinggung antaranggota"],answer:0,explain:"Kalau umpan balik hanya muncul saat ada masalah, ia selalu terasa buruk. Menjadikannya rutin membuatnya biasa & aman.",hint:"Rutin + disambut + fokus perbaikan, atau hanya saat marah / dilarang?"},
{n:80,type:"open",micro:"Menganalisis sesi umpan balik yang gagal",q:"Dalam sesi umpan balik kelompok, Bima berkata ke Sari: 'Idemu nggak masuk akal, kamu emang suka mikir aneh-aneh. Semua bagian presentasimu harus diganti.' Sari langsung diam dan tidak bicara lagi sepanjang sesi. Jelaskan minimal 4 kesalahan Bima, lalu tulis ulang umpan baliknya menjadi versi yang membangun.",explain:"Jawaban baik menyebut minimal 4 kesalahan (serangan pribadi, terlalu umum/melebih-lebihkan, tidak menyebut kekuatan, tanpa alasan/contoh spesifik, nada kasar / di depan umum) dan menulis ulang menjadi umpan balik yang: menyebut kekuatan spesifik, menunjuk bagian spesifik yang perlu diperbaiki dengan alasan, memberi saran konkret, nada membantu.",hint:"Cari: serangan pribadi, generalisasi berlebihan, tak ada kekuatan disebut, tak ada alasan/contoh, nada & tempat.",sample:"Kesalahan Bima: (1) Menyerang pribadi ('kamu emang suka mikir aneh-aneh') alih-alih membahas ide/hasil — ini memicu rasa malu dan pertahanan. (2) Terlalu umum dan melebih-lebihkan ('semua bagian harus diganti') sehingga tidak ada arah konkret dan terasa seperti vonis. (3) Tidak menyebutkan satu pun hal yang sudah baik, jadi Sari tidak tahu apa yang harus dipertahankan. (4) Tidak memberi alasan atau contoh spesifik — 'nggak masuk akal' tanpa menunjuk bagian mana dan kenapa. (5) Nada dan pilihan katanya kasar, disampaikan di depan kelompok. Akibatnya Sari menutup diri dan sesi jadi tidak produktif. Versi yang membangun: 'Sari, bagian datamu di slide 2 kuat dan gampang dibaca. Untuk ide utamamu, aku masih belum kebayang bagaimana penerapannya di sekolah yang anggarannya kecil — bisa dijelaskan bagian itu? Mungkin kesimpulanmu perlu satu-dua contoh konkret supaya lebih meyakinkan. Sisanya menurutku sudah oke.'"},
{n:81,type:"mcq",micro:"Kasus: umpan balik ke teman yang mudah tersinggung",q:"Temanmu berbakat tapi sangat mudah tersinggung oleh kritik. Kamu tetap perlu menyampaikan masukan penting. Pendekatan:",options:["Sampaikan saja seperti biasa dengan nada yang sama, dan anggap kalau ia tersinggung itu sepenuhnya urusan dirinya sendiri, bukan tanggung jawabmu","Pilih waktu tenang berdua, awali dengan kekuatannya yang tulus, sampaikan satu hal saja dengan sangat spesifik + niat membantu, & tanyakan pendapatnya","Jangan memberi masukan agar ia tidak sedih dan marah, walaupun masalahnya bisa merugikan seluruh kelompok pada akhirnya, dan itu lebih aman"],answer:1,explain:"Menyesuaikan penyampaian dengan orangnya (lebih lembut, lebih sedikit, lebih spesifik) tetap menjaga kejujuran isi.",hint:"Sesuaikan bentuk tanpa membuang isi, atau diam / cuek?"},
{n:82,type:"mcq",micro:"Kasus: kamu menerima umpan balik yang salah/tidak akurat",q:"Seseorang memberi umpan balik berdasarkan salah paham tentang apa yang kamu kerjakan. Respons:",options:["'Kamu nggak ngerti apa-apa soal pekerjaanku, jadi jangan sok memberi komentar tentang hal yang tidak kamu pahami.'","Diam saja & membiarkan salah paham itu berlanjut, lalu mengeluh kepada teman-teman lain tentang orang yang memberi masukan","'Terima kasih. Sepertinya ada bagian yang belum kujelaskan — sebenarnya X bekerja begini. Tapi poinmu soal Y aku catat.'"],answer:2,explain:"Luruskan fakta dengan tenang + tetap ambil bagian yang tetap berlaku. Jangan menyerang & jangan diam.",hint:"Luruskan tenang + ambil yang berlaku, atau menyerang / diam?"},
{n:83,type:"tf",micro:"Refleksi: umpan balik adalah hadiah yang canggung",q:"Benar atau Salah: Umpan balik yang membuatmu tidak nyaman hampir selalu berarti si pemberi bermaksud menjatuhkanmu, jadi sebaiknya diabaikan.",answer:false,explain:"Sebaliknya, umpan balik jujur & membangun sering terasa tidak nyaman justru karena mengenai hal nyata. Orang yang berani jujur dengan niat baik sering lebih membantu daripada yang hanya memuji.",hint:"Umpan balik jujur = mengganggu, atau hadiah berharga?"},
{n:84,type:"mcq",micro:"Kasus: umpan balik untuk pemimpinmu",q:"Ketua kelompokmu terlalu mendominasi & jarang mendengar anggota. Cara memberi umpan balik:",options:["Berdua: 'Kak, menurutku ide-idemu bagus. Cuma, kadang anggota lain belum sempat ngomong. Gimana kalau tiap rapat kita kasih giliran? Aku rasa hasilnya bisa lebih kaya.'","Diam saja & mengeluh kepada anggota lain di belakangnya, tanpa pernah menyampaikan masalah itu kepada ketua secara langsung, lalu berharap ia menyadarinya sendiri","Menyerangnya di tengah rapat di depan banyak orang: 'Kamu diktator! Nggak mau dengerin pendapat kami, dasar egois dan tukang perintah ya!'"],answer:0,explain:"Umpan balik ke atas: pribadi, akui yang baik, sebut dampak spesifik, tawarkan solusi konkret, bingkai sebagai manfaat bersama.",hint:"Pribadi + akui + dampak + solusi, atau mengeluh / menyerang?"},
{n:85,type:"order",micro:"Membangun kebiasaan meminta umpan balik",q:"Urutkan langkah membiasakan diri meminta umpan balik secara rutin.",items:["Setelah tugas/latihan, pilih satu orang yang paham & tepercaya","Ajukan satu pertanyaan spesifik: 'Satu hal apa yang paling bisa aku tingkatkan?'","Catat jawabannya tanpa membela diri, tanyakan contoh bila perlu","Terapkan, lalu tunjukkan hasilnya & minta cek ulang"],answer:[0,1,2,3],explain:"Pilih orang tepat → tanya spesifik → catat tanpa defensif → terapkan & cek ulang. Ulangi sampai jadi kebiasaan.",hint:"Apa yang dilakukan sebelum bertanya?"},
{n:86,type:"mcq",micro:"Kasus: umpan balik menyakitkan yang kemudian terbukti benar",q:"Setahun lalu seseorang guru berkata tulisanmu 'penuh kalimat berputar'. Kamu marah saat itu. Sekarang membaca tulisan lamamu, kamu setuju. Pelajaran:",options:["Sebaiknya tidak mendengarkan kritik dari siapa saja, karena kritik hanya menyakitkan dan tak berguna bagi penulis pemula maupun lanjutan","Umpan balik yang menyakitkan saat itu bisa jadi paling berharga; menahan defensif & menyimpannya untuk direnungkan sering terbayar","Guru itu memang jahat & suka menjatuhkan murid, sehingga seluruh komentarnya tidak pantas dipertimbangkan sampai kapan pun"],answer:1,explain:"Reaksi awal terhadap umpan balik sering emosi. Memberi diri waktu untuk mencernanya bisa mengubah pandangan.",hint:"Kritik menyakitkan bisa berharga, atau selalu abaikan?"},
{n:87,type:"tf",micro:"Umpan balik tanpa tindak lanjut",q:"Benar atau Salah: Kalau kamu terus meminta umpan balik tetapi tidak pernah menerapkan apa pun, lama-lama orang akan berhenti memberimu masukan yang jujur.",answer:true,explain:"Orang menilai apakah masukannya berarti. Kalau selalu diabaikan, mereka beralih ke 'bagus kok' agar tidak buang tenaga.",hint:"Minta tapi tak pernah terapkan — orang tetap jujur, atau berhenti?"},
{n:88,type:"mcq",micro:"Kasus: memberi umpan balik lintas perbedaan",q:"Kamu memberi umpan balik ke teman dari latar budaya berbeda & tidak yakin cara yang pas. Sikap bijak:",options:["Berasumsi bahwa cara menyampaikan yang kamu pakai sama dengan cara temanmu, sehingga tak perlu menyesuaikan, karena kalian sama-sama pelajar","Menghindari pemberian umpan balik kepada teman itu seumur pertemanan, supaya tak ada salah paham budaya, walau ia memintanya","Tetap spesifik & hormat, perhatikan reaksinya, & bila ragu tanyakan 'cara aku menyampaikan tadi oke, atau ada yang kurang enak?'"],answer:2,explain:"Norma umpan balik (seberapa langsung, di mana, oleh siapa) berbeda antar budaya & keluarga. Peka & mau bertanya membantu.",hint:"Peka + tanyakan bila ragu, atau berasumsi / menghindar?"},
{n:89,type:"mcq",micro:"Kasus: umpan balik untuk perilaku yang menyakiti orang lain",q:"Kamu melihat temanmu terus meledek anggota kelompok lain sampai anak itu murung. Umpan balik yang tepat:",options:["Berdua: 'Aku perhatiin candaanmu ke Rio bikin dia keliatan down. Mungkin kamu nggak sadar, tapi tolong distop ya.'","Membiarkan saja karena itu 'cuma bercanda' dan anak yang diledek akan terbiasa dengan sendirinya setelah beberapa lama","Meledek balik temanmu di depan umum supaya ia merasakan sendiri bagaimana rasanya ditertawakan banyak orang"],answer:0,explain:"Umpan balik juga alat menjaga orang lain: sebut perilaku spesifik + dampaknya + permintaan jelas, secara pribadi.",hint:"Sebut perilaku + dampak + permintaan berdua, atau diam / membalas?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Sekolahmu akan memulai 'budaya umpan balik' antar teman untuk tugas-tugas. Sebagai bagian dari tim penggagas, tulis panduan singkat berisi minimal 6 aturan main agar umpan balik antar teman bermanfaat dan tidak melukai. Jelaskan alasan tiap aturan.",explain:"Jawaban baik memuat minimal 6 aturan konkret dengan alasan, mencakup ide inti bab: minta izin/baca kesiapan, sebut kekuatan spesifik, fokus karya bukan pribadi, batasi jumlah saran + alasan + langkah konkret, kritik privat / puji publik, nada membantu + penerima memilih (bukan perintah), larangan menjatuhkan + jalur pengaduan, menutup lingkaran dengan cek ulang.",hint:"Turunkan tiap prinsip bab jadi satu aturan: izin, kekuatan dulu, fokus karya, batasi & beralasan, privat vs publik, masukan bukan perintah, anti-bully, tutup lingkaran.",sample:"Panduan umpan balik antar teman: (1) Minta izin atau pastikan orangnya siap sebelum memberi masukan — karena masukan yang tidak diminta bisa terasa menghakimi. (2) Selalu sebut minimal satu hal yang sudah baik dan spesifik — supaya orang tahu apa yang dipertahankan dan lebih terbuka. (3) Fokus pada karya/perilaku, bukan pribadi ('paragraf ini' bukan 'kamu memang ceroboh') — karena label pribadi memicu pertahanan dan tidak memberi arah. (4) Beri maksimal 2-3 saran, masing-masing dengan alasan dan langkah konkret — supaya orang tidak kewalahan dan tahu harus berbuat apa. (5) Sampaikan kritik secara pribadi, bukan di depan kelas; puji boleh di depan umum — karena koreksi publik mempermalukan. (6) Pemberi memakai nada membantu dan bahasa 'menurutku'; penerima mendengarkan sampai selesai, berterima kasih, dan boleh memilih mana yang diterapkan — karena umpan balik adalah masukan, bukan perintah, dan keputusan akhir ada pada pemilik karya. (7) Dilarang memakai sesi umpan balik untuk membalas dendam atau menjatuhkan; guru mengawasi dan siapa pun boleh melapor bila merasa dilecehkan. (8) Setelah revisi, penerima boleh menunjukkan hasilnya dan meminta cek ulang — supaya lingkaran umpan balik tertutup dan terasa berguna."},
{n:91,type:"mcq",micro:"Kasus: umpan balik saat kamu lelah/kesal",q:"Kamu diminta menilai draf teman tapi sedang lelah & mudah tersulut. Sikap bertanggung jawab:",options:["Asal beri 'bagus kok' tanpa membaca dengan teliti agar urusannya cepat selesai & kamu bisa segera beristirahat","Tunda: 'Aku mau kasih masukan yang bener buat kamu, tapi aku lagi capek. Besok pagi ya biar aku bisa fokus & adil.'","Paksakan memberi penilaian sekarang juga, walaupun kemungkinan besar terlalu keras karena kamu sedang mudah tersulut"],answer:1,explain:"Kondisimu memengaruhi kualitas & keadilan umpan balikmu. Menunda dengan jelas lebih menghargai temanmu.",hint:"Tunda dengan jujur, atau paksakan keras / asal?"},
{n:92,type:"tf",micro:"Refleksi: memberi & menerima adalah keterampilan terpisah yang keduanya dilatih",q:"Benar atau Salah: Menjadi baik dalam MEMBERI umpan balik & menjadi baik dalam MENERIMA umpan balik adalah dua keterampilan berbeda, dan keduanya bisa dilatih.",answer:true,explain:"Seseorang bisa jago menyampaikan masukan tapi buruk menerimanya, atau sebaliknya. Latih keduanya.",hint:"Satu keterampilan, atau dua yang berbeda?"},
{n:93,type:"mcq",micro:"Kasus: umpan balik & pujian yang tidak tulus",q:"Kamu diminta memberi umpan balik & tergoda hanya memuji agar disukai, padahal ada masalah nyata. Risikonya:",options:["Tak ada risiko, semua senang, dan kamu tetap disukai serta dipercaya oleh temanmu itu untuk waktu lama, karena kamu bersikap manis padanya","Ia akan langsung tahu kamu berbohong dan marah besar saat itu juga, lalu tak mau lagi berteman denganmu, karena merasa dikhianati sahabat sendiri","Temanmu kehilangan kesempatan memperbaiki & bisa terkejut/kecewa nanti saat dinilai orang lain; kepercayaannya padamu juga bisa turun"],answer:2,explain:"Kebaikan sejati kadang berarti menyampaikan yang tidak menyenangkan. Pujian palsu menunda masalah & merugikan temanmu.",hint:"Menunda masalah & merugikan teman, atau tak ada risiko?"},
{n:94,type:"mcq",micro:"Kasus: menerima umpan balik publik yang tak terduga",q:"Di depan kelas, seseorang tiba-tiba mengkritik presentasimu dengan keras. Respons yang menjaga ketenangan:",options:["'Terima kasih masukannya. Ada beberapa poin yang mau aku pahami lebih jauh — boleh kita bahas setelah kelas?'","Membalas menyerang orang itu di depan kelas dengan nada tinggi supaya semua teman tahu bahwa kritiknya tidak benar","Menangis dan meninggalkan ruangan tanpa berkata apa-apa, lalu tak mau presentasi lagi di depan kelas nanti"],answer:0,explain:"Menerima dengan tenang + memindahkan diskusi detail ke tempat privat menjaga martabat kedua pihak.",hint:"Terima tenang + pindahkan ke privat, atau menyerang balik / kabur?"},
{n:95,type:"tf",micro:"Umpan balik & rasa memiliki",q:"Benar atau Salah: Umpan balik paling efektif bila disampaikan sebagai perintah tegas ('ganti bagian ini'), karena usul & pertanyaan hanya membuat orang bingung & lambat bertindak.",answer:false,explain:"Sebaliknya, umpan balik sebagai usul & pertanyaan ('bagaimana kalau...?') membuat orang tetap merasa memiliki karyanya, sehingga lebih mungkin menerapkan perbaikan dengan sepenuh hati.",hint:"Usul menjaga rasa memiliki, atau tak berpengaruh?"},
{n:96,type:"mcq",micro:"Kasus: refleksi setelah memberi umpan balik",q:"Cara melatih keterampilan memberi umpan balik lewat refleksi:",options:["Menganggap kalau orang tersinggung oleh masukanmu itu salah mereka sendiri, bukan salah caramu, jadi tak perlu mengubah apa-apa, lalu lanjut memberi masukan serupa","Setelah memberi masukan, tanya diri: apakah aku menyebut kekuatan? apakah spesifik? apakah fokus pada karya? bagaimana reaksinya & apa yang bisa kuperbaiki?","Tidak meninjau kembali cara kamu memberi masukan, karena merasa dirimu sudah baik dan benar, sehingga latihan tak diperlukan lagi, dan itu menghemat waktu"],answer:1,explain:"Meninjau umpan balik yang kamu berikan (& reaksinya) menyempurnakan caramu menyampaikannya di lain waktu.",hint:"Evaluasi jujur, atau tak pernah meninjau?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti memberi & menerima umpan balik:",options:["Umpan balik berarti mengkritik habis-habisan semua kekurangan orang lain supaya mereka cepat berubah dan jera; saat menerima, turuti semua masukan tanpa memilah, bagaimanapun nadanya, kapan pun datangnya, dan dari mana pun asalnya, karena begitulah cara cepat berkembang","Hindari semua umpan balik, baik memberi maupun menerima, supaya orang tak tersinggung atau bertengkar; kalau terpaksa, sampaikan hal umum saja dan jangan menyebutkan hal spesifik atau perilaku seseorang, karena itu cara paling aman untuk menjaga hubungan di dalam kelompok","Beri umpan balik yang spesifik, fokus pada perilaku/hasil (bukan pribadi), seimbang (kekuatan + perbaikan), dengan niat membantu di waktu & tempat yang tepat; terima dengan mendengar penuh, klarifikasi, berterima kasih, lalu memilah — bukan menuruti semua atau menolak semua"],answer:2,explain:"Ringkasan: memberi = spesifik + perilaku + seimbang + niat baik + waktu-tempat tepat; menerima = dengar + klarifikasi + terima kasih + pilah.",hint:"Spesifik, perilaku, seimbang, niat baik; dengar, klarifikasi, terima kasih, pilah — rangkai."},
{n:98,type:"tf",micro:"Refleksi: umpan balik melayani pertumbuhan",q:"Benar atau Salah: Baik memberi maupun menerima umpan balik pada akhirnya bertujuan sama: membantu seseorang (atau sebuah tim) menjadi lebih baik dari sebelumnya.",answer:true,explain:"Kalau tujuan itu hilang — berubah jadi menang, menyerang, atau menyenangkan — umpan balik kehilangan gunanya.",hint:"Tujuan sama-sama pertumbuhan, atau berbeda?"},
{n:99,type:"mcq",micro:"Kasus: memulai kebiasaan umpan balik",q:"Cara termudah mulai membangun kebiasaan umpan balik yang sehat:",options:["Mulai dari umpan balik positif spesifik ke satu orang hari ini ('cara kamu X tadi membantu banget'), lalu latih memberi satu saran membangun minggu ini","Langsung mengkritik orang-orang di sekitarmu hari ini juga tentang kekurangan mereka, supaya kebiasaan itu cepat terbentuk, lalu catat reaksi mereka","Menunggu sampai kamu menjadi ahli yang sangat berpengalaman & dihormati banyak orang, baru kemudian berani mulai memberi umpan balik"],answer:0,explain:"Umpan balik positif spesifik adalah titik masuk yang aman & langsung menguatkan hubungan.",hint:"Mulai dari positif spesifik, atau kritik semua / menunggu ahli?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi umpan balik",q:"Tulis 'aturan pribadi memberi & menerima umpan balik' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: cek kesiapan + privat, kekuatan spesifik dulu, fokus perilaku + alasan + langkah, batasi jumlah, saat menerima: dengar penuh + klarifikasi + terima kasih + pilah nanti, tutup lingkaran, tunda saat emosi/lelah.",hint:"Ambil satu pelajaran tiap fase — izin & privat, kekuatan dulu, fokus perilaku, batasi jumlah, dengar & pilah, tutup lingkaran, tunda saat lelah — jadikan aturan 'aku akan...'.",sample:"Contoh aturan pribadi: (1) Sebelum memberi kritik yang belum diminta, aku cek kesiapan orangnya dan menyampaikannya berdua, bukan di depan umum — karena koreksi publik mempermalukan. (2) Aku selalu menyebut minimal satu hal spesifik yang sudah baik — supaya orang tahu apa yang dipertahankan dan lebih terbuka. (3) Aku fokus pada karya/perilaku yang bisa diubah, bukan pada pribadi, dan tiap saranku kukasih alasan + langkah konkret — supaya berguna, bukan melukai. (4) Aku membatasi diri pada 1-3 poin terpenting — supaya orang tidak kewalahan. (5) Saat menerima umpan balik, aku mendengarkan sampai selesai tanpa membela diri, bertanya contoh bila perlu, berterima kasih, lalu memilah setelah tenang — karena umpan balik adalah masukan, bukan perintah, dan memutuskan saat defensif sering keliru. (6) Aku menutup lingkaran: memberi tahu si pemberi apa yang kuubah, atau menunjukkan hasil revisi — supaya orang mau jujur lagi. (7) Kalau aku sedang lelah atau kesal, aku menunda memberi umpan balik sampai bisa adil."},
];
